export interface InsuredItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: InsuredItem[];
}

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export interface StepResult {
  premium?: number;
  payout?: number;
  remainingCap?: number;
}

const PROCESSING_FEE = 5;
const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};
const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
const COMPONENT_BASE_PREMIUM = 25;
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const CURSE_SURCHARGE_PERCENT = 50;
const PERCENT = 100;
// Amounts are kept in hundredths of a G so percentages stay exact until the final rounding.
const HUNDREDTHS_PER_G = 100;

function countAlikeItems(items: InsuredItem[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const item of items) counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  return counts;
}

function alikeComponentsBasePremium(count: number): number {
  return count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * COMPONENT_BASE_PREMIUM;
}

function basePremiumForAlikeItems(type: string, count: number): number {
  if (COMPONENT_TYPES.has(type)) return alikeComponentsBasePremium(count);
  return count * MAIN_ITEM_BASE_PREMIUMS[type];
}

function policyBasePremium(items: InsuredItem[]): number {
  let sum = 0;
  for (const [type, count] of countAlikeItems(items)) sum += basePremiumForAlikeItems(type, count);
  return sum;
}

function roundPremiumInMhpcoFavor(amountInHundredths: number): number {
  return Math.ceil(amountInHundredths / HUNDREDTHS_PER_G);
}

function withFirstInsuranceSurcharge(policyBaseInHundredths: number): number {
  return (policyBaseInHundredths * (PERCENT + FIRST_INSURANCE_SURCHARGE_PERCENT)) / PERCENT;
}

function itemBasePremium(item: InsuredItem): number {
  return MAIN_ITEM_BASE_PREMIUMS[item.type] ?? COMPONENT_BASE_PREMIUM;
}

function itemSurchargesInHundredths(items: InsuredItem[]): number {
  return items
    .filter((item) => item.cursed)
    .reduce((sum, item) => sum + (itemBasePremium(item) * HUNDREDTHS_PER_G * CURSE_SURCHARGE_PERCENT) / PERCENT, 0);
}

function quote(step: QuoteStep): number {
  const policyBaseInHundredths = policyBasePremium(step.items) * HUNDREDTHS_PER_G;
  const premiumInHundredths =
    withFirstInsuranceSurcharge(policyBaseInHundredths) + itemSurchargesInHundredths(step.items);
  return roundPremiumInMhpcoFavor(premiumInHundredths) + PROCESSING_FEE;
}

export function runScenario(scenario: Scenario): { results: StepResult[] } {
  return { results: scenario.steps.map((step) => ({ premium: quote(step) })) };
}
import { describe, expect, it } from "vitest";
import { type InsuredItem, runScenario } from "./claim-office";

function premiumFor(items: InsuredItem[], yearsWithMHPCO = 0): number {
  const { results } = runScenario({ customer: { yearsWithMHPCO }, steps: [{ op: "quote", items }] });
  return results[0].premium as number;
}

function alikeComponents(type: string, count: number): InsuredItem[] {
  return Array.from({ length: count }, () => ({ type }));
}

describe("claim office quote", () => {
  it("empty item list -> premium 5 G (only the processing fee)", () => {
    expect(premiumFor([])).toBe(5);
  });
  it("plain sword for newcomer -> 100 base + 10 first insurance + 5 fee = 115 G", () => {
    expect(premiumFor([{ type: "sword" }])).toBe(115);
  });
  it("plain amulet for newcomer -> 60 base + 6 first insurance + 5 fee = 71 G", () => {
    expect(premiumFor([{ type: "amulet" }])).toBe(71);
  });
  it("plain staff for newcomer -> 80 base + 8 first insurance + 5 fee = 93 G", () => {
    expect(premiumFor([{ type: "staff" }])).toBe(93);
  });
  it("plain potion for newcomer -> 40 base + 4 first insurance + 5 fee = 49 G", () => {
    expect(premiumFor([{ type: "potion" }])).toBe(49);
  });
  it("2 runes -> 50 G base premium -> 55 + 5 = 60 G", () => {
    expect(premiumFor(alikeComponents("rune", 2))).toBe(60);
  });
  it("1 moonstone -> 25 G base premium -> 27.5 + 5 = 32.5 -> 33 G (rounded up)", () => {
    expect(premiumFor([{ type: "moonstone" }])).toBe(33);
  });
  it("3 runes -> 60 G base premium (block) -> 66 + 5 = 71 G", () => {
    expect(premiumFor(alikeComponents("rune", 3))).toBe(71);
  });
  it("4 runes -> 100 G base premium (no block) -> 110 + 5 = 115 G", () => {
    expect(premiumFor(alikeComponents("rune", 4))).toBe(115);
  });
  it("7 runes -> 175 G base premium -> 192.5 + 5 = 197.5 -> 198 G", () => {
    expect(premiumFor(alikeComponents("rune", 7))).toBe(198);
  });
  it("2 runes + 1 moonstone -> 75 G base premium (different types, no block) -> 82.5 + 5 -> 88 G", () => {
    expect(premiumFor([...alikeComponents("rune", 2), { type: "moonstone" }])).toBe(88);
  });
  it("3 runes + 3 moonstones -> 120 G base premium (two blocks) -> 132 + 5 = 137 G", () => {
    expect(premiumFor([...alikeComponents("rune", 3), ...alikeComponents("moonstone", 3)])).toBe(137);
  });
  it("newcomer with a cursed sword (steel, enchantment 3) -> 165 G", () => {
    expect(premiumFor([{ type: "sword", material: "steel", enchantment: 3, cursed: true }], 0)).toBe(165);
  });
});

